<script setup lang="ts">import{onMounted,ref}from'vue';import http from'../api/http';const rows=ref<any[]>([]),total=ref(0),dialog=ref(false),form=ref<any>({materialCode:'',materialName:'',materialType:'RAW',baseUnitCode:'EA'});async function load(){const{data}=await http.get('/mdm/materials',{params:{page:1,size:20}});rows.value=data.data.content;total.value=data.data.totalElements}async function create(){await http.post('/mdm/materials',form.value);dialog.value=false;form.value={materialCode:'',materialName:'',materialType:'RAW',baseUnitCode:'EA'};load()}async function submit(r:any){await http.post(`/mdm/materials/${r.id}/submit`);load()}onMounted(load)</script>
<template><section><div class="toolbar"><div><h1 class="page-title">物料主数据</h1><p class="page-subtitle">统一管理物料编码、分类、版本和发布状态；发布后自动分发到下游业务系统</p></div><el-button type="primary" @click="dialog=true">新建物料</el-button></div><el-card><div class="governance"><span class="status-dot"></span>治理规则：草稿物料不可被 ERP、MES、WMS 等系统引用，必须完成审批发布。</div><el-table :data="rows" stripe><el-table-column prop="materialCode" label="物料编码"/><el-table-column prop="materialName" label="物料名称" min-width="180"/><el-table-column prop="materialType" label="类别"/><el-table-column prop="status" label="状态"><template #default="{row}"><el-tag :type="row.status==='PUBLISHED'?'success':row.status==='PENDING'?'warning':'info'">{{row.status}}</el-tag></template></el-table-column><el-table-column prop="versionNo" label="版本"/><el-table-column label="操作" width="130"><template #default="{row}"><el-button v-if="row.status==='DRAFT'||row.status==='REJECTED'" type="primary" link @click="submit(row)">提交审批</el-button></template></el-table-column></el-table><div class="table-footer">共 {{total}} 条记录</div></el-card><el-dialog v-model="dialog" title="新建物料" width="520px"><el-form label-width="88px"><el-form-item label="物料编码"><el-input v-model="form.materialCode"/></el-form-item><el-form-item label="物料名称"><el-input v-model="form.materialName"/></el-form-item><el-form-item label="类别"><el-select v-model="form.materialType"><el-option label="原材料" value="RAW"/><el-option label="半成品" value="SEMI"/><el-option label="成品" value="FINISHED"/></el-select></el-form-item><el-form-item label="基本单位"><el-input v-model="form.baseUnitCode"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="create">保存草稿</el-button></template></el-dialog></section></template><style scoped>.governance{margin-bottom:15px;padding:10px 12px;border-radius:8px;background:#f5f9ff;color:#6680a0;font-size:12px}.table-footer{padding-top:14px;color:#91a0b4;font-size:12px}</style>
